import type { H3Event } from 'h3'
import { useRuntimeConfig } from 'nitropack/runtime'
// Virtual module generated by this module's own `setup()` (see `defineVirtualRegistry` in `module.ts`) -
// only resolvable once consumed inside a real Nitro build.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { staticItems, sources } from '#menus/server-sources'
import { type MenuItem, type ParsedMenuPath, collectMenuItems, matchesMenuGroup, parseMenuPath, sortByOrder } from '../utils/menu'
import { processMenuStore as menus, pushMenuItems, resetMenus } from '../app/utils/state'
import type { MenuSource } from '../../types'

type MenuSourceEntry = { menu: string, source: MenuSource }

// Sources (`runtime/menus.ts`) push through `extendMenuItem` into the shared menu state, which on the
// server is one instance per process. Populate it once, behind a single promise, so concurrent requests
// neither interleave nor duplicate items. Dynamic sources therefore see the runtime config of the process.
let registered: Promise<void> | undefined

function registerItems(): Promise<void> {
  registered ??= (async () => {
    resetMenus(menus)

    for (const [menu, groups] of Object.entries(staticItems as Record<string, Record<string, MenuItem[]>>)) {
      for (const [group, items] of Object.entries(groups)) {
        if (items.length > 0) pushMenuItems(menus, menu, group, items)
      }
    }

    for (const { menu, source } of sources as MenuSourceEntry[]) {
      const items: Parameters<MenuSource>[0] = []
      await source(items)
      if (items.length > 0) pushMenuItems(menus, menu, '', items)
    }
  })().catch((error) => {
    registered = undefined
    throw error
  })
  return registered
}

// Matches the locale-suffixed collection naming convention defined by `@frigear-nu/base`'s
// `content.config.ts` (e.g. `config` -> `config_en`).
function localizedCollectionName(name: string, locale?: string) {
  return locale ? `${name}_${locale.replace(/-/g, '_')}` : name
}

type MenusPublicConfig = {
  content?: Record<string, { collection: string, field: string } | undefined>
}

async function loadContentItems(event: H3Event, menu: string, parsed: ParsedMenuPath, locale: string | undefined): Promise<MenuItem[]> {
  const config = (useRuntimeConfig(event).public.menus ?? {}) as MenusPublicConfig
  const source = config.content?.[menu]
  if (!source) return []

  // `@nuxt/content` is an optional peer: only imported when a menu opted into the content source
  // (the build-time check in `module.ts` guarantees it is installed then).
  // eslint-disable-next-line @typescript-eslint/ban-ts-comment
  // @ts-ignore -- optional peer, not resolvable for this package's own types.
  const { queryCollection } = await import('@nuxt/content/server')
  const entry = await queryCollection(event, localizedCollectionName(source.collection, locale)).first()
  const items = ((entry as Record<string, unknown> | null)?.[source.field] as MenuItem[] | undefined) ?? []

  return items.filter((item: MenuItem) => {
    const group = item.group ?? ''
    return parsed.wildcard ? matchesMenuGroup(group, parsed.group) : group === parsed.group
  })
}

/**
 * Server counterpart of the client `useMenu`: resolves a menu's (or menu group's) items merged from
 * every source - `extendMenu` items, `runtime/menus.ts` sources and the `@nuxt/content` source -
 * with content items first, sorted by `order`. Accepts the same paths, wildcards included.
 * Labels are not translated; pass `locale` to read a localized content collection.
 *
 * ```ts
 * export default defineEventHandler(event => useMenu(event, 'dashboard.*'))
 * ```
 */
export const useMenu = async (event: H3Event, path: string, options: { locale?: string } = {}): Promise<MenuItem[]> => {
  const parsed = parseMenuPath(path)
  await registerItems()

  const content = await loadContentItems(event, parsed.menu, parsed, options.locale)
  return sortByOrder([...content, ...collectMenuItems(menus[parsed.menu], parsed)])
}
